function solve(digits) {
    if (digits.length === 0) return [];
    const map = { 2: 'abc', 3: 'def', 4: 'ghi', 5: 'jkl', 6: 'mno', 7: 'pqrs', 8: 'tuv', 9: 'wxyz' };
    let result = [''];
    for (const d of digits) {
        const next = [];
        for (const prefix of result) {
            for (const ch of map[d]) next.push(prefix + ch);
        }
        result = next;
    }
    return result;
}

