function solve(s) {
    const result = [];
    const path = [];
    const isPal = (l, r) => {
        while (l < r) {
            if (s[l] !== s[r]) return false;
            l += 1;
            r -= 1;
        }
        return true;
    };
    const dfs = (start) => {
        if (start === s.length) {
            result.push([...path]);
            return;
        }
        for (let end = start; end < s.length; end++) {
            if (isPal(start, end)) {
                path.push(s.slice(start, end + 1));
                dfs(end + 1);
                path.pop();
            }
        }
    };
    dfs(0);
    return result;
}

