function solve(nums) {
    const p = [1, ...nums, 1];
    const n = p.length;
    const dp = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let len = 2; len < n; len++) {
        for (let i = 0; i + len < n; i++) {
            const j = i + len;
            let best = 0;
            for (let k = i + 1; k < j; k++) {
                best = Math.max(best, dp[i][k] + dp[k][j] + p[i] * p[k] * p[j]);
            }
            dp[i][j] = best;
        }
    }
    return dp[0][n - 1];
}

