            const mid = Math.floor((lo + hi) / 2);
            if (ends[mid] <= jobs[i][0]) lo = mid + 1;
            else hi = mid;
        }
        best[i + 1] = Math.max(best[i], best[lo] + jobs[i][2]);
    }
