function solve(num, target) {
    const result = [];
    const dfs = (index, expr, value, last) => {
        if (index === num.length) {
            if (value === target) result.push(expr);
            return;
        }
        for (let end = index + 1; end <= num.length; end++) {
            if (end - index > 1 && num[index] === '0') break;
            const part = num.slice(index, end);
            const n = Number(part);
            if (index === 0) {
                dfs(end, part, n, n);
            } else {
                dfs(end, expr + '+' + part, value + n, n);
                dfs(end, expr + '-' + part, value - n, -n);
                dfs(end, expr + '*' + part, value - last + last * n, last * n);
            }
        }
    };
    dfs(0, '', 0, 0);
    return result.sort();
}

