function solve(s1, s2) {
    if (s1.length !== s2.length) return false;
    const memo = new Map();
    const check = (i, j, len) => {
        const key = i + ',' + j + ',' + len;
        if (memo.has(key)) return memo.get(key);
        const a = s1.slice(i, i + len);
        const b = s2.slice(j, j + len);
        let ok = false;
        if (a === b) {
            ok = true;
        } else {
            const count = new Array(26).fill(0);
            for (let k = 0; k < len; k++) {
                count[a.charCodeAt(k) - 97] += 1;
                count[b.charCodeAt(k) - 97] -= 1;
            }
            if (count.every((x) => x === 0)) {
                for (let k = 1; k < len && !ok; k++) {
                    if (check(i, j, k) && check(i + k, j + k, len - k)) ok = true;
                    else if (check(i, j + len - k, k) && check(i + k, j, len - k)) ok = true;
                }
            }
        }
        memo.set(key, ok);
        return ok;
    };
    return check(0, 0, s1.length);
}

